    tag "modules_nfcore"
    tag "htslib"
    tag "htslib/bgziptabix"

    test("sarscov2 - vcf - decompress") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/vcf/test.vcf', checkIfExists: true),
                    [],
                    []
                ]
                input[1] = 'decompress' // action
                input[2] = false // make_index
                input[3] = 'vcf' // out_ext
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() },
                { assert process.out.output.get(0).get(1).endsWith('.vcf') },
                { assert process.out.index.size() == 0 }
            )
        }

    }

    test("sarscov2 - vcf - compress - index") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
