                    []
                ]
                input[1] = 'compress' // action
                input[2] = true // make_index
                input[3] = 'vcf' // out_ext
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() },
                { assert process.out.output.get(0).get(1).endsWith('.vcf.gz') },
                { assert process.out.index.get(0).get(1).endsWith('.vcf.gz.tbi') }
            )
        }

    }

    test("sarscov2 - vcf + regions - compress - index") {
        when {
