                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/vcf/test.vcf.gz.tbi', checkIfExists: true),
                    file('https://raw.githubusercontent.com/luisas/test-datasets/refs/heads/add-bedgraph-subset-illumina/data/genomics/sarscov2/illumina/bed/test.bed', checkIfExists: true)
                ]
                input[1] = 'compress' // action
                input[2] = true // make_index
                input[3] = 'vcf' // out_ext
                """
            }
        }

        then {
            assertAll (
                { assert process.success },
                { assert snapshot(
                    sanitizeOutput(process.out),
                    path(process.out.output[0][1]).vcf.getVariantsMD5(),
                ).match() }
            )
        }
    }

